package com.crm.crm.controller;
import com.crm.crm.entity.*; import com.crm.crm.service.ClientService; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*;
@Controller @RequestMapping("/clients") public class ClientController {private final ClientService s; public ClientController(ClientService s){this.s=s;} @GetMapping public String list(Model m){m.addAttribute("clients",s.findAll());return "clients/list";} @GetMapping("/new") public String form(Model m){m.addAttribute("client",new Client());m.addAttribute("statuses",ClientStatus.values());return "clients/form";} @GetMapping("/edit/{id}") public String edit(@PathVariable Long id,Model m){return s.findById(id).map(c->{m.addAttribute("client",c);m.addAttribute("statuses",ClientStatus.values());return "clients/form";}).orElse("redirect:/clients");} @PostMapping("/save") public String save(@Valid @ModelAttribute Client client,BindingResult br,Model m){if(br.hasErrors()){m.addAttribute("statuses",ClientStatus.values());return "clients/form";}s.save(client);return "redirect:/clients";} @PostMapping("/delete/{id}") public String delete(@PathVariable Long id){s.delete(id);return "redirect:/clients";}}
